// 姓名詳批：五格、三才、三運的傳統解說，以及名字和八字喜用的配合。
//
// nameReading(analyseName(full, analysis), analysis) returns plain data for the page. The levels are this project's
// own (src/core/name.js: 康熙筆畫, two 81-number tables, 半吉 where they differ, the 三才 table); the traditional texts
// come from src/core/name-texts.js (generated by scripts/make-name-texts.mjs). Nothing here changes the simulation:
// the name's small tilt is effects in name.js.
//
// English (core/tr.js): every sentence goes through tr(), so the Chinese is what it always was and the English page
// gets src/i18n/en/name.json. The fields the code compares stay Chinese in both (key, element, level, the roles, the
// characters); the page shows them with trw(). Names stay in characters, with their romanisation: 陳怡君 (Chen Yi-chun).
import { SHULI_TEXTS, SANCAI_TEXTS, YUNSHI } from "./name-texts.js";
import { fiveGrids, shuli, LEVEL_ZH, numberElement, trAs, shownName } from "./name.js";
import { elementRoles } from "./detail.js";
import { ELEMENTS } from "./analysis.js";
import { tr, trw, trJoin, readingLang } from "./tr.js";

const GRIDS = ["天格", "人格", "地格", "外格", "總格"];
// The scored grids and their weights within 五格數理. 天格 comes with the surname and is not scored.
const SCORED = { 人格: 0.4, 總格: 0.25, 地格: 0.2, 外格: 0.15 };
const GENERATES = { 木: "火", 火: "土", 土: "金", 金: "水", 水: "木" };
const CONTROLS = { 木: "土", 土: "水", 水: "火", 火: "金", 金: "木" };
const wrap = n => ((n - 1) % 80) + 1;   // as in shuli(): past 81 the numbers start over

const en = () => readingLang() === "en";
// Sentences put together: nothing between them in Chinese, a space in English.
const cat = (...parts) => parts.filter(Boolean).join(en() ? " " : "");
// A list in a sentence: 甲、乙 in Chinese, "a, b and c" in English.
const andList = list => (!en() ? list.join("、") : list.length < 2 ? list.join("") : `${list.slice(0, -1).join(", ")} and ${list[list.length - 1]}`);
const orList = (list, zh) => (!en() ? list.join(zh) : list.length < 2 ? list.join("") : `${list.slice(0, -1).join(", ")} or ${list[list.length - 1]}`);
// Elements or roles in a sentence, in the page's language.
const termList = list => andList(en() ? list.map(trw) : list);
// The Day Master's stem: 甲 in Chinese, "Jia (甲)" in English.
const PINYIN = { 甲: "Jia", 乙: "Yi", 丙: "Bing", 丁: "Ding", 戊: "Wu", 己: "Ji", 庚: "Geng", 辛: "Xin", 壬: "Ren", 癸: "Gui" };
const stemShown = s => (en() && PINYIN[s] ? `${PINYIN[s]} (${s})` : s);
// A clause as a sentence of its own.
const sentence = t => (en() ? `${t.charAt(0).toUpperCase()}${t.slice(1)}.` : `${t}。`);

export const SCORE_LABEL = "傳統姓名學評分（僅供參考）";
const VERDICTS = [[90, "整體配置很好"], [82, "整體配置不錯"], [74, "整體中上"], [66, "整體普通，有幾處不理想"], [0, "傳統上評價不高"]];
const CALM = {
  grid: "傳統上這是凶數，但名字只是命理裡很小的一環，要和八字、大運合起來看，在這個模擬裡也不影響壽命和重病；這是遊戲，不需要為此改名。",
  sancai: "三才只看三個格的五行生剋，是很粗略的判斷，影響有限。",
  fortune: "這是依五行生剋推出的傳統說法，僅供參考。",
};
const NOTES = [
  "姓名學的流派很多，筆畫算法和 81 數理表都有不同版本。這裡用康熙筆畫；兩種數理表說法不同的數，算半吉。",
  "五格、三才、三運的解說都是傳統說法，僅供參考。名字在這個模擬裡的影響很小，每個領域最多 ±5%，而且不影響壽命和重病。",
];
const CREDIT = "81 數理、三才、三運的解說文字取自 shunshi-naming-core（MIT 授權，Copyright (c) 2026 Shunshi.AI），轉成臺灣用字。";
const FORTUNES = [
  ["成功運", "天格", "人格與天格的關係，看上進與事業能否順利，以及長輩、上司與時勢的助力。"],
  ["基礎運", "地格", "人格與地格的關係，看根基穩不穩：家庭、住所、身體，以及部屬和晚輩的助力。"],
  ["社交運", "外格", "人格與外格的關係，看人際是否融洽，以及外在環境和別人怎麼對待你。"],
];

// How element a (of grid an) stands to element b (of grid bn), in the usual words.
function relation(an, a, bn, b) {
  if (a === b) return tr("{an}與{bn}同屬{a}，比和", { an, bn, a });
  if (GENERATES[a] === b) return tr("{an}（{a}）生{bn}（{b}）", { an, a, bn, b });
  if (GENERATES[b] === a) return tr("{bn}（{b}）生{an}（{a}）", { an, a, bn, b });
  if (CONTROLS[a] === b) return tr("{an}（{a}）剋{bn}（{b}）", { an, a, bn, b });
  return tr("{bn}（{b}）剋{an}（{a}）", { an, a, bn, b });
}

// How each grid is added up, from the primary stroke counts (the same formulas as fiveGrids in name.js).
function formulas(n, s, g) {
  const t = c => `${c.ch} ${c.strokes.primary}`, ONE = tr("1（假一）");
  const all = [...s, ...g], sum = all.reduce((a, c) => a + c.strokes.primary, 0);
  const f = {
    天格: s.length > 1 ? `${t(s[0])} + ${t(s[1])}` : `${t(s[0])} + ${ONE}`,
    人格: `${t(s[s.length - 1])} + ${t(g[0])}`,
    地格: g.length > 1 ? g.map(t).join(" + ") : `${t(g[0])} + ${ONE}`,
    外格: `${s.length > 1 ? t(s[0]) : ONE} + ${g.length > 1 ? t(g[g.length - 1]) : ONE}`,
    總格: all.map(t).join(" + ") + (sum > 81 ? tr(" = {sum}，超過 81 減 80", { sum }) : ""),
  };
  return Object.fromEntries(GRIDS.map(k => [k, `${f[k]} = ${n.grids[k].value}`]));
}

// The other values each grid takes under the other stroke readings of disputed characters (at most 16 readings, as
// in name.js).
function alternatives(n, surnameLength) {
  let combos = [[]];
  for (const c of n.chars) combos = combos.flatMap(p => c.strokes.all.map(x => [...p, x])).slice(0, 16);
  const out = Object.fromEntries(GRIDS.map(k => [k, new Set()]));
  for (const list of combos) {
    const v = fiveGrids(list.slice(0, surnameLength), list.slice(surnameLength));
    for (const k of GRIDS) if (v[k] !== n.grids[k].value) out[k].add(v[k]);
  }
  return Object.fromEntries(GRIDS.map(k => [k, [...out[k]].sort((a, b) => a - b)]));
}

// Whether the grid's level changes between stroke readings.
const levelVaries = g => (g.good > 0 && g.good < g.readings) || g.mean !== g.level;

function gridReading(key, g, formula, alts) {
  const judged = key in SCORED, t = SHULI_TEXTS[wrap(g.value)], notes = [];
  if (!judged) notes.push(tr("天格由姓氏決定，是祖先傳下來的，多數流派不論吉凶，這裡不計分，只介紹這個數的傳統說法。"));
  if (judged && !g.agree) notes.push(tr("兩種數理表說法不同（一說{first}、一說{second}），這裡算半吉。", { first: g.tables[0], second: g.tables[1] }));
  // The source marks 1 as impossible in a real name: 人格 and 外格 are at least 2 (1 + 1).
  if ((key === "人格" || key === "外格") && g.value < 2) notes.push(tr("人格和外格最小是 2，不會是這個數，請檢查筆畫。"));
  if (alts.length) {
    const level = v => LEVEL_ZH[shuli(v).level];
    const values = trJoin(alts.map(v => (!judged ? String(v) : en() ? `${v} (${trw(level(v))})` : `${v}（${level(v)}）`)));
    const tail = judged && levelVaries(g) ? tr("；{readings} 種算法裡有 {good} 種是吉", { readings: g.readings, good: g.good }) : "";
    notes.push(tr("依筆畫有爭議的字的其他算法，這一格也可能是 {values}{tail}。", { values, tail }));
  }
  if (judged && g.level < 0) notes.push(tr(CALM.grid));
  return {
    key, value: g.value, element: g.element, level: judged ? LEVEL_ZH[g.level] : "不論吉凶", judged, role: tr(g.role), formula,
    poem: tr(t.poem), keywords: t.keywords.map(k => tr(k)), text: tr(t.text), note: cat(...notes),
  };
}

// 名字與八字: each given-name character's 字形五行 (from its radical, when it reads plainly) and 數理五行 (from its
// strokes) against the chart. The elements are named as in detail.js: 用神 and 喜神 (the chart's `useful`) help, 忌神
// and 仇神 (`avoid`) go against it, 閒神 neither. The surname is left out: it comes with the family.
const SIGN = { 用神: 1, 喜神: 1, 閒神: 0, 仇神: -1, 忌神: -1 };
function elementsReading(given, analysis, who) {
  const roles = analysis ? elementRoles(analysis) : null;
  const word = e => (roles[e] === "閒神" ? tr("{element}是閒神，不喜不忌", { element: e }) : tr("{element}是{role}", { element: e, role: roles[e] }));
  const both = e => (roles[e] === "閒神" ? tr("兩者都屬{element}，是閒神，不喜不忌", { element: e }) : tr("兩者都屬{element}，是{role}", { element: e, role: roles[e] }));
  // 「怡」「君」, or in English 怡 (Yi) and 君 (Chun); a repeated character once.
  const quote = chars => (en() ? andList([...new Set(chars)].map(who.char)) : [...new Set(chars)].map(ch => `「${ch}」`).join(""));
  const lines = list => cat(...list.filter((c, i) => list.findIndex(x => x.ch === c.ch) === i).map(c => c.text));   // a repeated character once
  const chars = given.map(c => {
    const alt = [...new Set(c.strokes.all.slice(1).filter(x => numberElement(x) !== c.number).map(x => tr("{strokes} 畫屬{element}", { strokes: x, element: numberElement(x) })))];
    const strokes = tr("{strokes} 畫屬{element}{other}", { strokes: c.strokes.primary, element: c.number, other: alt.length ? tr("（另一種算法 {alternatives}）", { alternatives: trJoin(alt) }) : "" });
    const raw = { ch: who.char(c.ch) }, form = c.form;
    const plain = form ? trAs("「{ch}」字形屬{form}，數理 {strokes}。", { form, strokes }, raw) : trAs("「{ch}」字形五行不明確，只看數理：{strokes}。", { strokes }, raw);
    const out = { ch: c.ch, form: form || "", number: c.number, strokes: c.strokes.all, formRole: "", numberRole: "", verdict: "", text: plain, value: 0, mixed: false };
    if (!roles) return out;
    const own = c.form && c.form !== c.number ? [c.form, c.number] : [c.number];
    out.value = own.reduce((sum, e) => sum + SIGN[roles[e]], 0) / own.length;
    out.mixed = own.some(e => SIGN[roles[e]] > 0) && own.some(e => SIGN[roles[e]] < 0);
    out.formRole = c.form ? roles[c.form] : "";
    out.numberRole = roles[c.number];
    out.verdict = tr(out.value === 1 ? "對八字有幫助" : out.value > 0 ? "對八字有些幫助" : out.value === -1 ? "和八字不合" : out.value < 0 ? "和八字略有不合" : out.mixed ? "一喜一忌，作用互相抵消" : "對八字的影響不大");
    const verdict = out.verdict;
    out.text = !form ? trAs("「{ch}」字形五行不明確，只看數理：{strokes}，{judged}，{verdict}。", { strokes, judged: word(c.number), verdict }, raw)
      : form === c.number ? trAs("「{ch}」字形屬{form}，數理 {strokes}：{judged}，{verdict}。", { form, strokes, judged: both(c.number), verdict }, raw)
      : trAs("「{ch}」字形屬{form}，數理 {strokes}：{formRole}，{numberRole}，{verdict}。", { form, strokes, formRole: word(form), numberRole: word(c.number), verdict }, raw);
    return out;
  });

  const about = tr("姓氏是祖先傳下來的，不列入比較。字形五行看部首，數理五行看筆畫的尾數（1、2 木，3、4 火，5、6 土，7、8 金，9、0 水）。用神、喜神對命盤有利，忌神、仇神不利，閒神影響不大。");
  const strip = ({ value, mixed, ...rest }) => rest;
  if (!roles) return { chars: chars.map(strip), useful: [], avoid: [], roles: {}, about, text: cat(tr("沒有命盤資料，只列出名字的五行，沒有和喜用神比較。"), lines(chars)), short: "", balance: null };

  const order = [...new Set([...analysis.useful, ...analysis.avoid, ...ELEMENTS])];
  const named = r => termList(order.filter(e => roles[e] === r));
  const dm = analysis.dayMaster;
  const useful = named("用神") ? tr("用神{useful}{favourable}", { useful: named("用神"), favourable: named("喜神") ? tr("，喜神{elements}", { elements: named("喜神") }) : "" }) : tr("喜用神不明顯");
  const avoid = named("忌神") ? tr("忌神{unfavourable}{hostile}", { unfavourable: named("忌神"), hostile: named("仇神") ? tr("，仇神{elements}", { elements: named("仇神") }) : "" }) : tr("沒有明顯的忌神");
  const idle = named("閒神") ? tr("；{elements}是閒神", { elements: named("閒神") }) : "";
  const intro = trAs("八字日主是{stem}{element}，{strength}。{useful}；{avoid}{idle}。", { element: dm.element, strength: analysis.strength, useful, avoid, idle }, { stem: stemShown(dm.stem) });
  const helps = chars.filter(c => c.value > 0).map(c => c.ch), hurts = chars.filter(c => c.value < 0).map(c => c.ch);
  const mixed = chars.filter(c => c.value === 0 && c.mixed).map(c => c.ch);
  const balance = chars.reduce((sum, c) => sum + c.value, 0) / chars.length;
  // The roles the helping and the hurting characters touch, e.g. 用神 or 仇神.
  const touched = (list, sign) => termList(["用神", "喜神", "忌神", "仇神"].filter(r => Math.sign(SIGN[r]) === sign && chars.some(c => list.includes(c.ch) && (c.numberRole === r || c.formRole === r))));
  const good = touched(helps, 1), bad = touched(hurts, -1);
  let end, short;
  if (helps.length && !hurts.length) {
    end = trAs("{chars}補到{good}，傳統上叫做「補八字」，被認為能補足命局所缺，是名字加分的地方。", { good }, { chars: quote(helps) });
    short = tr("名字的五行補到{good}", { good });
  } else if (hurts.length && !helps.length) {
    end = trAs("{chars}落在{bad}上，傳統上認為會加重命局的偏頗；不過名字只是很小的一個因素，影響有限。", { bad }, { chars: quote(hurts) });
    short = tr("名字的五行落在{bad}上", { bad });
  } else if (helps.length) {
    const overall = tr(balance > 0 ? "整體還是偏向有利" : balance < 0 ? "整體略偏不利" : "整體打平");
    end = trAs("{helps}補到{good}，{hurts}落在{bad}上，一好一壞，{overall}。", { good, bad, overall }, { helps: quote(helps), hurts: quote(hurts) });
    short = tr("名字的五行有喜有忌");
  } else if (mixed.length) {
    end = trAs("{chars}一喜一忌，作用互相抵消，整體對八字不加分也不扣分。", {}, { chars: quote(mixed) });
    short = tr("名字的五行喜忌互相抵消");
  } else {
    end = tr("名字的五行都是閒神，不喜不忌，對八字不加分也不扣分。");
    short = tr("名字的五行不喜不忌");
  }
  return { chars: chars.map(strip), useful: [...analysis.useful], avoid: [...analysis.avoid], roles, about, text: cat(intro, lines(chars), end), short, balance };
}

// 傳統姓名學評分（僅供參考）, 0–100. Every part is on the same scale, a level from −1 to +1 giving 75 + 25 × level
// points, so each part scores 50 to 100:
//   五格數理 60 %: 人格 0.40, 總格 0.25, 地格 0.20, 外格 0.15, each at its level in name.js (吉 +1, 半吉 0, 凶 −1),
//                  averaged over the stroke readings when a character is disputed. 天格 is not scored.
//   三才 20 %:     its level (大吉 +2 … 大凶 −2) halved.
//   八字喜用 20 %: the given name's balance: the mean over its characters of the mean over each character's known
//                  elements (字形 when known, 數理) of +1 用神 or 喜神, 0 閒神, −1 忌神 or 仇神. Without a chart this
//                  part is left out and the other two count 75 % and 25 %.
// A name that is 吉 everywhere and fits the chart scores 100; one that is 凶 everywhere and goes against it, 50.
function scoreOf(n, balance) {
  const points = level => 75 + 25 * level;
  const parts = [
    ["五格數理", Object.entries(SCORED).reduce((s, [k, w]) => s + w * points(n.grids[k].mean), 0), 0.6],
    ["三才", points(n.sancai.level / 2), 0.2],
  ];
  if (balance !== null) parts.push(["八字喜用", points(balance), 0.2]);
  const total = parts.reduce((s, [, , w]) => s + w, 0);
  const value = Math.round(parts.reduce((s, [, p, w]) => s + p * w, 0) / total);
  const note = tr(balance !== null
    ? "五格數理占 60%（人格 40%、總格 25%、地格 20%、外格 15%），三才占 20%，名字和八字喜用神的配合占 20%；每一項都換算成 50 到 100 分。"
    : "五格數理占 75%（人格 40%、總格 25%、地格 20%、外格 15%），三才占 25%；沒有命盤資料，不計八字喜用神。每一項都換算成 50 到 100 分。");
  return { value: Math.max(0, Math.min(100, value)), note, parts: parts.map(([part, p, w]) => ({ part: tr(part), points: Math.round(p), weight: Math.round(w / total * 100) })) };
}

const COUNTS = { 2: "「{ch}」有 {strokes} 畫兩種算法", 3: "「{ch}」有 {strokes} 畫三種算法" };
function disputedReading(n, disputedChars, who) {
  if (!disputedChars.length) return "";
  const list = trJoin(disputedChars.map(c => trAs(COUNTS[c.strokes.all.length] || "「{ch}」有 {strokes} 畫幾種算法", { strokes: orList(c.strokes.all, "、") }, { ch: who.char(c.ch) })), "，");
  const used = trJoin(disputedChars.map(c => trAs("「{ch}」{strokes} 畫", { strokes: c.strokes.primary }, { ch: who.char(c.ch) })));
  const readings = n.grids.總格.readings;
  const changed = Object.keys(SCORED).filter(k => levelVaries(n.grids[k])).map(k => tr("{grid}在 {readings} 種算法裡有 {good} 種是吉", { grid: k, readings, good: n.grids[k].good }));
  const rest = changed.length ? tr("{changed}，其他各格的吉凶不變", { changed: trJoin(changed, "，") }) : tr("各格的吉凶都不受影響");
  return trAs("{list}。五格以{used}為準，其他 {others} 種算法也都算過：{rest}。", { others: readings - 1, rest }, { list, used });
}

// The reading, or { error } when the name could not be analysed:
//   { full, surname, given, summary, score, scoreLabel, scoreNote, scoreParts: [{ part, points, weight }], strokes,
//     grids: [{ key, value, element, level, judged, role, formula, poem, keywords, text, note }]   天格 人格 地格 外格 總格
//     sancai: { elements, level, about, relation, text, note },
//     yunshi: { 成功運, 基礎運, 社交運: { from: "人格", to, elements, relation, level, about, text, note } },
//     elements: { chars: [{ ch, form, number, strokes, formRole, numberRole, verdict, text }], useful, avoid, roles,
//                 about, text },
//     disputed, notes, credit }
// Grid levels are 吉, 半吉 or 凶 (天格: 不論吉凶); 三才 and 運 levels 大吉 … 大凶. No field is null: an empty string
// means there is nothing to say (form "" is a character without a clear 字形五行).
export function nameReading(n, analysis = null) {
  if (!n || n.error) return { error: (n && n.error) || tr("沒有辦法分析這個名字。") };
  const who = shownName(n.full);
  const surnameLength = [...n.surname].length;
  const s = n.chars.slice(0, surnameLength), given = n.chars.slice(surnameLength);
  const f = formulas(n, s, given), alts = alternatives(n, surnameLength);
  const grids = GRIDS.map(k => gridReading(k, n.grids[k], f[k], alts[k]));

  const [tian, ren, di] = [...n.sancai.elements];
  const sancai = {
    elements: n.sancai.elements, level: n.sancai.name,
    about: tr("三才是天格、人格、地格的五行配置，傳統上用來看成功、根基與身心是否安穩。"),
    relation: tr("天格屬{tian}、人格屬{ren}、地格屬{di}：{first}，{second}。", { tian, ren, di, first: relation("天格", tian, "人格", ren), second: relation("人格", ren, "地格", di) }),
    text: tr(SANCAI_TEXTS[n.sancai.elements]),
    note: n.sancai.level < 0 ? tr(CALM.sancai) : "",
  };

  const yunshi = {};
  for (const [name, other, about] of FORTUNES) {
    const a = n.grids.人格.element, b = n.grids[other].element, e = YUNSHI[name][a + b];
    yunshi[name] = { from: "人格", to: other, elements: a + b, relation: sentence(relation("人格", a, other, b)), level: e.level, about: tr(about), text: tr(e.text), note: e.level.includes("凶") ? tr(CALM.fortune) : "" };
  }

  const el = elementsReading(given, analysis, who);
  const score = scoreOf(n, el.balance);
  const disputedChars = n.chars.filter(c => c.strokes.all.length > 1);

  const scored = grids.filter(g => g.judged), count = l => scored.filter(g => g.level === l).length;
  const [good, half, bad] = ["吉", "半吉", "凶"].map(count);
  const renLevel = grids[1].level;
  const gridPart = good === 4 ? tr("人格、地格、外格、總格四格都是吉數")
    : bad === 4 ? tr("人格、地格、外格、總格四格都是凶數")
    : tr("計分的四格裡有 {counts}，主運人格{ren}", {
      counts: andList([good && tr("{good} 格吉", { good }), half && tr("{half} 格半吉", { half }), bad && tr("{bad} 格凶", { bad })].filter(Boolean)),
      ren: tr(renLevel === "吉" ? "是吉數" : renLevel === "凶" ? "是凶數" : "算半吉"),
    });
  // The verdict follows the score (over the random names of the simulation its median is 83, its 10th percentile 69
  // and its 90th 94), except that a 凶 主運 caps it: traditionally 人格 weighs more than the rest together.
  let at = VERDICTS.findIndex(([min]) => score.value >= min);
  if (renLevel === "凶") at = Math.max(at, 3);
  const overall = tr(VERDICTS[at][1]);
  const parts = { overall, gridPart, elements: sancai.elements, level: sancai.level, elementsShort: el.short };
  let summary = el.short ? trAs("「{name}」{overall}：{gridPart}，三才「{elements}」{level}；{elementsShort}。", parts, { name: who.name })
    : trAs("「{name}」{overall}：{gridPart}，三才「{elements}」{level}。", parts, { name: who.name });
  if (score.value < 66) summary = cat(summary, tr("不過名字只是很小的一個因素，這是模擬遊戲，不需要為此改名。"));

  return {
    full: n.full, surname: n.surname, given: n.given,
    summary,
    score: score.value, scoreLabel: tr(SCORE_LABEL), scoreNote: score.note, scoreParts: score.parts,
    strokes: trJoin(n.chars.map(c => `${c.ch} ${orList(c.strokes.all, " 或 ")}`)),
    grids, sancai, yunshi,
    elements: { chars: el.chars, useful: el.useful, avoid: el.avoid, roles: el.roles, about: el.about, text: el.text },
    disputed: disputedReading(n, disputedChars, who),
    notes: NOTES.map(x => tr(x)),
    credit: tr(CREDIT),
  };
}
